import { cn } from "@/lib/utils"

/**
 * The Assertly mark: a check whose short arm ends in a crosshair disc.
 * Colors come from the theme tokens, so it works in light and dark.
 * Static copies are generated by scripts/build-brand.mjs (keep the geometry in sync).
 */
export function LogoMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 64 64" aria-hidden="true" className={cn("shrink-0", className)}>
      <rect width="64" height="64" rx="15" className="fill-primary" />
      <g transform="translate(-2.25 0)">
        <g
          className="fill-primary-foreground stroke-primary-foreground"
          strokeWidth="10"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M20 31 L31 42 L51 22" fill="none" />
          <circle cx="21" cy="26.5" r="8.5" stroke="none" />
        </g>
        <g className="stroke-primary" strokeWidth="2.4" fill="none">
          <path d="M11.3 16.8 L30.7 36.2" />
          <path d="M30.7 16.8 L11.3 36.2" />
        </g>
      </g>
    </svg>
  )
}

export function Logo({ className }: { className?: string }) {
  return (
    <span className={cn("inline-flex items-center gap-2.5 font-bold tracking-tight", className)}>
      <LogoMark className="h-7 w-7" />
      Assertly
    </span>
  )
}
